_theme.customCss:
/* ===== 第1段 · 根主题 ===== */
.xt-root {
  --xt-bg: linear-gradient(175deg, #16161a, #0b0b0d);
  --xt-text: #f5f5f3;
  --xt-text-sub: rgba(245,245,243,0.72);
  --xt-text-muted: rgba(245,245,243,0.45);
  --xt-accent: #c9a86a;
  --xt-accent-bg: rgba(201,168,106,0.08);
  --xt-border: rgba(255,255,255,0.08);
  --xt-radius: 20px;
  --xt-radius-sm: 12px;
  --xt-font: -apple-system, BlinkMacSystemFont, "PingFang SC", "Segoe UI", sans-serif;
  background-color: #0b0b0d;
  border-radius: 34px;
  box-shadow:
    0 0 0 7px #0c0c0e,
    0 0 0 8px rgba(255,255,255,0.14),
    0 0 0 9px rgba(255,255,255,0.04),
    0 36px 90px rgba(0,0,0,0.7);
}

.xt-text-phonebar, .xt-text-userinfo,
.xt-text-tweet, .xt-text-imgdesc, .xt-text-statline, .xt-text-cmt_all,
.xt-text-musicsong, .xt-text-musiclyric, .xt-text-musicfeel,
.xt-text-douyin_video, .xt-text-douyin_bgm, .xt-text-douyin_caption,
.xt-text-douyin_stats, .xt-text-douyin_cmt,
.xt-text-zhihu_q, .xt-text-zhihu_a,
.xt-text-bili_title, .xt-text-bili_rest, .xt-text-bili_mycmt,
.xt-text-xh_title, .xt-text-xh_rest, .xt-text-xh_mycmt,
.xt-text-game,
.xt-text-album_1, .xt-text-album_2, .xt-text-album_3,
.xt-text-location,
.xt-text-order, .xt-text-delivery, .xt-text-wallet_app,
.xt-text-bills_expense, .xt-text-bills_income,
.xt-text-health_steps, .xt-text-health_sleep,
.xt-text-calendar_note, .xt-text-alarm,
.xt-text-chat_a_title, .xt-text-chat_b_title, .xt-text-chat_g_title,
.xt-text-call, .xt-text-fav,
.xt-text-p1body, .xt-text-p1cmt, .xt-text-p2body, .xt-text-p2cmt,
.xt-text-pollq, .xt-text-pollopt, .xt-text-pollinfo,
.xt-text-trends_hot, .xt-text-trends_view, .xt-text-history,
.xt-text-recommend_reminder,
.xt-text-reading_title, .xt-text-reading_quote, .xt-text-reading_note,
.xt-text-letter,
.xt-text-porn_title, .xt-text-porn_desc, .xt-text-porn_feel,
.xt-text-screentime, .xt-text-sms_1, .xt-text-sms_2, .xt-text-sms_3,
.xt-text-notify_1, .xt-text-notify_2, .xt-text-notify_3,
.xt-text-quickpanel,
.xt-text-weather_stamp, .xt-text-bottomnav {
  white-space: pre-wrap;
}
/* ===== 第2段 · 卡片与帖子 ===== */
.xt-card {
  background: #16161a;
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 20px;
  margin: 8px 10px;
  padding: 14px;
  box-shadow: 0 4px 16px rgba(0,0,0,0.25);
}
.xt-card-title {
  color: #c9a86a;
  font-size: 11px; font-weight: 700;
  letter-spacing: 2.5px;
  padding: 0 0 8px 10px;
  margin-bottom: 10px;
  border-bottom: 1px solid rgba(255,255,255,0.08);
  border-left: 3px solid #c9a86a;
}
.xt-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 4px 0 10px;
}
.xt-avatar {
  width: 44px; height: 44px;
  border-radius: 50%;
  border: 2px solid #c9a86a;
  box-shadow: 0 0 0 3px rgba(201,168,106,0.15);
  object-fit: cover;
  flex-shrink: 0;
}
.xt-name {
  flex: 1;
  font-size: 14px; font-weight: 800;
  color: #f5f5f3;
  line-height: 1.5;
}
.xt-text-tweet {
  font-size: 17px; font-weight: 550;
  line-height: 1.8; letter-spacing: 0.3px;
  color: #f5f5f3;
  padding: 12px 0;
  border-bottom: 1px solid rgba(255,255,255,0.07);
}
.xt-text-imgdesc {
  padding: 20px 14px;
  background: linear-gradient(180deg, #1c1c20, #19191d);
  border: 1px solid rgba(201,168,106,0.2);
  border-radius: 12px;
  margin: 10px 0;
  font-size: 13px;
  text-align: center;
  color: rgba(245,245,243,0.7);
}
.xt-text-statline {
  padding: 8px 0;
  font-size: 12.5px; letter-spacing: 1px;
  color: #c9a86a;
  text-align: center;
  border-top: 1px dashed rgba(201,168,106,0.25);
  border-bottom: 1px dashed rgba(201,168,106,0.25);
}
.xt-text-cmt_all {
  padding: 10px 0 2px;
  font-size: 13.5px;
  line-height: 2.1;
  color: rgba(245,245,243,0.75);
  border-top: 2px solid rgba(201,168,106,0.4);
  margin-top: 8px;
}
/* ===== 第3段 · 状态栏+网易云 ===== */
.xt-text-phonebar {
  position: relative;
  padding: 11px 58px 11px 16px;
  margin: 10px 10px 8px;
  background: #26262b;
  border: 1px solid rgba(255,255,255,0.10);
  border-radius: 14px;
  font-size: 12px; letter-spacing: 1px;
  color: rgba(245,245,243,0.85);
  text-align: left;
}
.xt-text-musicsong {
  background: linear-gradient(135deg, #2a1518, #1c1012);
  border: 1px solid rgba(236,65,65,0.3);
  border-left: 3px solid #ec4141;
  border-radius: 12px;
  padding: 10px 14px;
  font-size: 14px; font-weight: 700;
  color: #ff6b6b;
}
.xt-text-musiclyric {
  padding: 8px 14px 8px 18px;
  border-left: 2px solid rgba(236,65,65,0.35);
  font-style: italic;
  font-size: 13px; line-height: 1.9;
  color: rgba(245,245,243,0.75);
}
.xt-text-musicfeel {
  padding: 8px 14px;
  font-size: 13px; line-height: 1.8;
  color: rgba(245,245,243,0.85);
}
/* ===== 第4段 · 抖音 ===== */
.xt-text-douyin_video {
  position: relative;
  padding: 30px 16px;
  background: #0a0a0c;
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 14px;
  font-size: 13.5px; line-height: 1.9;
  color: rgba(245,245,243,0.78);
  text-align: center;
}
.xt-text-douyin_bgm {
  padding: 8px 14px 4px;
  font-size: 12.5px;
  color: rgba(245,245,243,0.6);
}
.xt-text-douyin_caption {
  padding: 2px 14px 8px;
  font-size: 14px;
  color: #f5f5f3;
}
.xt-text-douyin_stats {
  padding: 8px 14px;
  font-size: 13px;
  letter-spacing: 0.5px;
  color: #c9a86a;
  border-top: 1px dashed rgba(201,168,106,0.25);
}
.xt-text-douyin_cmt {
  padding: 10px 14px 2px;
  font-size: 12.5px; line-height: 2.2;
  color: rgba(245,245,243,0.7);
  border-top: 1px solid rgba(255,255,255,0.08);
}
/* ===== 第5段 · 知乎 ===== */
.xt-text-zhihu_q {
  padding: 14px 16px 12px;
  background: #f9fafc;
  border: 1px solid #0084ff;
  border-bottom: none;
  border-radius: 14px 14px 0 0;
  font-size: 14px; font-weight: 700;
  color: #0084ff;
  line-height: 1.6;
  margin: 0 !important;
}
.xt-text-zhihu_a {
  padding: 12px 16px 14px;
  background: #f9fafc;
  border: 1px solid #0084ff;
  border-top: none;
  border-radius: 0 0 14px 14px;
  font-size: 13.5px; line-height: 1.95;
  color: #18191a;
  margin: 0 !important;
}
.xt-text-zhihu_a::first-line {
  font-weight: 700;
  color: #18191a;
}
/* ===== 第6段 · B站 ===== */
.xt-text-bili_title {
  padding: 14px 16px 12px;
  background: #f9fafc;
  border: 1px solid #00a1d6;
  border-bottom: none;
  border-radius: 14px 14px 0 0;
  font-size: 14px; font-weight: 700;
  color: #00a1d6;
  line-height: 1.6;
  margin: 0 !important;
}
.xt-text-bili_rest {
  position: relative;
  padding: 12px 16px 28px;
  background: #f9fafc;
  border: 1px solid #00a1d6;
  border-top: none;
  border-bottom: none;
  border-radius: 0;
  font-size: 13px; line-height: 2;
  color: #18191a;
  margin: 0 !important;
}
.xt-text-bili_rest::after {
  content: "";
  position: absolute;
  left: 16px; right: 16px; bottom: 10px;
  height: 3px;
  border-radius: 2px;
  background: linear-gradient(90deg, #00a1d6 0 65%, #e0e2e6 65% 100%);
}
.xt-text-bili_mycmt {
  padding: 8px 12px 10px;
  background: #f0f6fa;
  border: 1px solid #00a1d6;
  border-top: none;
  border-radius: 0 0 14px 14px;
  font-size: 12.5px; line-height: 1.75;
  color: #18191a;
  margin: 0 !important;
}
.xt-text-bili_mycmt::before {
  content: "我的评论";
  display: block;
  font-size: 10px; font-weight: 700;
  letter-spacing: 2px;
  color: #00a1d6;
  margin-bottom: 4px;
}
/* ===== 第7段 · 小红书 ===== */
.xt-text-xh_title {
  padding: 14px 16px 12px;
  background: #f9fafc;
  border: 1px solid #ff3055;
  border-bottom: none;
  border-radius: 14px 14px 0 0;
  font-size: 14px; font-weight: 700;
  color: #ff3055;
  line-height: 1.6;
  margin: 0 !important;
}
.xt-text-xh_rest {
  padding: 12px 16px 12px;
  background: #f9fafc;
  border: 1px solid #ff3055;
  border-top: none;
  border-bottom: none;
  border-radius: 0;
  font-size: 13px; line-height: 2;
  color: #18191a;
  margin: 0 !important;
}
.xt-text-xh_mycmt {
  padding: 8px 12px 10px;
  background: #fdf0f3;
  border: 1px solid #ff3055;
  border-top: none;
  border-radius: 0 0 14px 14px;
  font-size: 12.5px; line-height: 1.75;
  color: #18191a;
  margin: 0 !important;
}
.xt-text-xh_mycmt::before {
  content: "我的评论";
  display: block;
  font-size: 10px; font-weight: 700;
  letter-spacing: 2px;
  color: #ff3055;
  margin-bottom: 4px;
}
/* ===== 第8段 · 游戏+相册 ===== */
.xt-text-game {
  position: relative;
  padding: 14px 16px 30px;
  background: linear-gradient(135deg, #241f3d, #151226);
  border: 1px solid rgba(139,124,240,0.4);
  border-left: 3px solid #8b7cf0;
  border-radius: 14px;
  font-size: 13.5px; line-height: 2;
  color: #f5f5f3;
}
.xt-text-game::first-line {
  color: #b8a8ff;
  font-weight: 700;
}
.xt-text-game::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 4px;
  background: linear-gradient(90deg, #8b7cf0, rgba(139,124,240,0.2));
  border-radius: 12px 12px 0 0;
}
.xt-text-game::after {
  content: "";
  position: absolute;
  left: 16px; right: 16px; bottom: 10px;
  height: 5px;
  border-radius: 3px;
  background: linear-gradient(90deg, #8b7cf0 0 70%, rgba(255,255,255,0.08) 70% 100%);
}
.xt-text-album_1,
.xt-text-album_2,
.xt-text-album_3 {
  position: relative;
  padding: 14px 16px;
  background: linear-gradient(160deg, #1c1c20, #131316);
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: 16px;
  font-size: 13.5px; line-height: 2;
  color: rgba(245,245,243,0.85);
  margin-bottom: 10px;
  box-shadow: inset 0 2px 3px rgba(0,0,0,0.4);
}
.xt-text-album_1::first-line,
.xt-text-album_2::first-line,
.xt-text-album_3::first-line {
  font-size: 11px;
  color: rgba(201,168,106,0.7);
}
/* ===== 第9段 · 位置/外卖/物流 ===== */
.xt-text-location {
  position: relative;
  padding: 12px 14px 12px 34px;
  background:
    linear-gradient(rgba(16,185,129,0.06) 1px, transparent 1px),
    linear-gradient(90deg, rgba(16,185,129,0.06) 1px, transparent 1px),
    #101d18;
  background-size: 20px 20px;
  border: 1px solid rgba(16,185,129,0.25);
  border-left: 3px solid #10b981;
  border-radius: 12px;
  font-size: 13.5px; line-height: 1.9;
  color: rgba(245,245,243,0.85);
}
.xt-text-order {
  background: linear-gradient(135deg, #2a2410, #1a1a14);
  border: 1px solid rgba(255,209,0,0.2);
  border-top: 3px solid #ffd100;
  border-radius: 12px;
  padding: 12px 14px;
  font-size: 13.5px; line-height: 2;
  color: rgba(245,245,243,0.85);
}
.xt-text-order::first-line {
  color: #ffd100;
  font-weight: 700;
}
.xt-text-delivery {
  position: relative;
  padding: 12px 14px;
  background: linear-gradient(135deg, #2a1a10, #1a1510);
  border: 1px solid rgba(255,102,0,0.25);
  border-left: 3px solid #ff6600;
  border-radius: 12px;
  font-size: 13.5px; line-height: 2;
  color: #f5f5f3;
}
.xt-text-delivery::first-line {
  color: #ff6600;
  font-weight: 700;
}
.xt-text-delivery::after {
  content: "";
  display: block;
  height: 4px;
  border-radius: 2px;
  margin-top: 10px;
  background: linear-gradient(90deg, #ff6600 0 65%, rgba(255,255,255,0.1) 65% 100%);
}
/* ===== 第10段 · 钱包/账单/健康/日程/闹钟 ===== */
.xt-text-wallet_app {
  position: relative;
  padding: 46px 18px 16px;
  border-radius: 16px;
  background: linear-gradient(135deg, #0e3a66, #1677ff);
  border: 1px solid rgba(22,119,255,0.5);
  box-shadow: 0 8px 24px rgba(0,0,0,0.4), inset 0 1px 0 rgba(255,255,255,0.15);
  font-size: 14px; line-height: 2;
  color: #f5f7fa; letter-spacing: 0.3px;
  margin-bottom: 8px;
}
.xt-text-bills_expense {
  padding: 12px 14px;
  background: #0d2b4d;
  border: 1px solid rgba(22,119,255,0.3);
  border-radius: 12px;
  font-size: 13px; line-height: 2;
  color: rgba(255,255,255,0.9);
  margin-bottom: 8px;
}
.xt-text-bills_expense::before {
  content: "支出";
  display: block;
  font-size: 10px; font-weight: 700;
  letter-spacing: 2.4px;
  color: #6db3ff;
  margin-bottom: 6px;
}
.xt-text-bills_income {
  padding: 12px 14px;
  background: #0d2b1e;
  border: 1px solid rgba(34,197,94,0.3);
  border-radius: 12px;
  font-size: 13px; line-height: 2;
  color: rgba(255,255,255,0.9);
}
.xt-text-bills_income::before {
  content: "收入";
  display: block;
  font-size: 10px; font-weight: 700;
  letter-spacing: 2.4px;
  color: #4ade80;
  margin-bottom: 6px;
}
.xt-row { display: flex; gap: 10px; }
.xt-row > * { flex: 1; }
.xt-ring { margin-bottom: 6px; }
.xt-ring-fill { stroke: #c9a86a; }
.xt-ring-value { color: #f5f5f3; font-weight: 700; }
.xt-ring-label { color: rgba(245,245,243,0.6); }
.xt-text-health_steps {
  padding: 10px 14px;
  background: #10231a;
  border: 1px solid rgba(34,197,94,0.2);
  border-left: 3px solid #22c55e;
  border-radius: 12px;
  font-size: 13.5px; line-height: 1.9;
  color: rgba(245,245,243,0.85);
  margin-top: 10px;
}
.xt-text-health_sleep {
  padding: 10px 14px;
  background: #10231a;
  border: 1px solid rgba(34,197,94,0.2);
  border-left: 3px solid #22c55e;
  border-radius: 12px;
  font-size: 13.5px; line-height: 1.9;
  color: rgba(245,245,243,0.85);
  margin-top: 8px;
}
/* 日程与待办：行距加大，一条一行 */
.xt-text-calendar_note {
  padding: 10px 14px 10px 16px;
  background: #1e1e22;
  border: 1px solid rgba(255,255,255,0.07);
  border-left: 3px solid #c9a86a;
  border-radius: 12px;
  font-size: 13.5px; line-height: 2.3;
  color: rgba(245,245,243,0.75);
}
.xt-text-alarm {
  padding: 12px 14px;
  background: #211d16;
  border: 1px solid rgba(201,168,106,0.18);
  border-left: 3px solid #c9a86a;
  border-radius: 12px;
  font-size: 13.5px; line-height: 2.1;
  color: #f5f5f3;
}
/* ===== 第11段 · 微信 ===== */
.xt-text-chat_a_title,
.xt-text-chat_b_title,
.xt-text-chat_g_title {
  text-align: center;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 1px;
  color: #f5f5f3;
  padding: 4px 0 10px;
  margin-bottom: 10px;
  border-bottom: 1px solid rgba(7,193,96,0.35);
}
.xt-bubble,
.xt-bubble-left,
.xt-bubble-right,
